const languages = ['km', 'zh', 'vi', 'tl', 'ms'];
export const qualityTranslations = Object.fromEntries(languages.map((language, index) => [language,
  Object.fromEntries(Object.entries(rows).map(([english, translated]) => [english, translated[index]]))
]));

export function translateQualityText(language, value) {
  if (language === 'en' || typeof value !== 'string') return value;
  const leading = value.match(/^\s*/)?.[0] || '';
  const trailing = value.match(/\s*$/)?.[0] || '';
  const core = value.trim();
  const dictionary = qualityTranslations[language] || {};
  const section = core.match(/^(\d+\s*[·.]\s*)(.+)$/);
  const indexedLabel = core.match(/^(.+?)\s+(\d+)$/);
  const padInspector = core.match(/^Pad inspector\s+(.+?)\s+·\s+unverified$/);
  const translated = (section && dictionary[section[2]] ? section[1] + dictionary[section[2]] : null)
    || dictionary[core]
    || (indexedLabel && dictionary[indexedLabel[1]] ? `${dictionary[indexedLabel[1]]} ${indexedLabel[2]}` : null)
    || (padInspector && dictionary['Pad inspector'] && dictionary.unverified
      ? `${dictionary['Pad inspector']} ${padInspector[1]} · ${dictionary.unverified}` : null)
    || core;
  return leading + translated + trailing;
}
